import time
from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity, ttl=None, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self._data = OrderedDict()  # key -> (value, expires_at or None)

    def _expired(self, expires_at):
        return expires_at is not None and self.clock() >= expires_at

    def _purge(self):
        if self.ttl is None:
            return
        now = self.clock()
        dead = [k for k, (_, exp) in self._data.items() if exp is not None and now >= exp]
        for k in dead:
            del self._data[k]

    def get(self, key, default=None):
        entry = self._data.get(key)
        if entry is None:
            return default
        value, exp = entry
        if exp is not None and self.clock() >= exp:
            del self._data[key]
            return default
        self._data.move_to_end(key)
        return value

    def put(self, key, value):
        if key in self._data:
            del self._data[key]
        exp = None if self.ttl is None else self.clock() + self.ttl
        self._data[key] = (value, exp)
        self._purge()
        while len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __len__(self):
        self._purge()
        return len(self._data)

    def __contains__(self, key):
        entry = self._data.get(key)
        if entry is None:
            return False
        exp = entry[1]
        if exp is not None and self.clock() >= exp:
            del self._data[key]
            return False
        return True
```

Edge case: capacity validation — `capacity < 1` raises ValueError. What about non-integers? Not needed.

A note about `_purge` in put: the order of deletion — first purge expired entries, then evict LRU. Since we're inserting the new key at the end, the purge won't delete it (just created, and expires_at = now+ttl > now if ttl>0. What about ttl=0? ttl=0 means it expires immediately: clock() >= t+0 → expired. In that case, purge would delete the key we just inserted. That's fine and consistent with the spec.) In fact, when ttl=0, exp = now >= now → expired. Purge will delete it. len would then be smaller. Consistent with the spec.

But note: purge only deletes expired entries; since we inserted the new key at the end, evicting LRU entries won't evict the key we just put (unless capacity < 1 which isn't possible… when capacity=1 and ttl=None, after put len=1 so no problem).

One subtle point: `get` on a key whose value is None — entry is a tuple so it's not None, and a stored None value works fine too.

